INSERT INTO public.prayers (title, text, category, tags, image_url, author_id, author_name, created_at, prayer_count, latin_text, parent_prayer_id, is_devotion)
VALUES
('Veni Creator Spiritus', 'Vinde Espírito Criador, a nossa alma visitai e enchei os corações com vossos dons celestiais. Vós sois chamado o Intercessor de Deus excelso dom sem par, a fonte viva, o fogo, o amor, a unção divina e salutar. Sois o doador dos sete dons e sois poder na mão do Pai, por Ele prometido a nós, por nós seus feitos proclamai. A nossa mente iluminai, os corações enchei de amor, nossa fraqueza encorajai, qual força eterna e protetor. Nosso inimigo repeli, e concedei-nos a vossa paz, se pela graça nos guiais, o mal deixamos para trás. Ao Pai e ao Filho Salvador, por vós possamos conhecer que procedeis do Seu amor, fazei-nos sempre firmes crer. Amém!', 'Diárias', ARRAY['#catolicoapp', '#comuns'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Oração a Santo Antônio', 'A verdadeira Oração para Santo Antônio Lembrai-vos, glorioso Santo Antônio, amigo do Menino Jesus, filho querido de Maria Imaculada, de que, nunca se ouviu dizer que alguém daqueles que têm recorrido a vós e implorado a vossa proteção, tenha sido por vós abandonado. Animado de igual confiança, venho a vós fiel consolador e amparador dos aflitos. Gemendo sob o peso dos meus pecados, me prostro a vossos pés, e pecador como sou, ouso a me apresentar diante de vós. Não rejeiteis, pois, a minha súplica (fazer o pedido) , vós que sois tão poderoso junto ao Coração de Jesus , mas escutai-a favoravelmente e dignai-vos a atendê-la. Amém. O que pedir na Oração de Santo Antônio? Na oração de Santo Antônio, você pode pedir por diversas graças, como a solução de problemas no amor, a benção do matrimônio, a reconciliação em relacionamentos, a recuperação de objetos perdidos e a intercessão em causas urgentes. Muitos fiéis também recorrem a Santo Antônio para pedir por paz, saúde e proteção para suas famílias. Acredita-se que, por sua grande proximidade com Deus, Santo Antônio é um poderoso intercessor em todas as necessidades. Se você está enfrentando dificuldades, reze com fé e confie na ajuda de Santo Antônio.', 'Santos', ARRAY['#catolicoapp', '#intercessao-dos-santos'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Ladainha de São José', 'Senhor, tende piedade de nós . Jesus Cristo, tende piedade de nós . Senhor, tende piedade de nós . Jesus Cristo, ouvi-nos . Jesus Cristo, atendei-nos. Deus, Pai dos Céus, tende piedade de nós . Deus Filho, Redentor do mundo, tende piedade de nós . Deus Espírito Santo, tende piedade de nós . Santíssima Trindade, que sois um só Deus, tende piedade de nós . Santa Maria, rogai por nós . São José, rogai por nós . Ilustre filho de Davi, rogai por nós . Luz dos Patriarcas, rogai por nós . Esposo da Mãe de Deus, rogai por nós . Casto guarda da Virgem, rogai por nós . Sustentador do Filho de Deus, rogai por nós . Zeloso defensor de Jesus Cristo, rogai por nós . Chefe da Sagrada Família, rogai por nós . José justíssimo, rogai por nós . José castíssimo, rogai por nós . José prudentíssimo, rogai por nós . José fortíssimo, rogai por nós . José obedientíssimo, rogai por nós . José fidelíssimo, rogai por nós . Espelho de paciência, rogai por nós . Amante da pobreza, rogai por nós . Modelo dos trabalhadores, rogai por nós . Honra da vida de família, rogai por nós . Guarda das virgens, rogai por nós . Sustentáculo das famílias, rogai por nós . Alívio dos miseráveis, rogai por nós . Esperança dos doentes, rogai por nós . Patrono dos moribundos, rogai por nós . Terror dos demônios, rogai por nós . Protetor da Santa Igreja, rogai por nós . Cordeiro de Deus que tirais os pecados do mundo, perdoai-nos, Senhor . Cordeiro de Deus que tirais os pecados do mundo, ouvi-nos, Senhor . Cordeiro de Deus que tirais os pecados do mundo, tende piedade de nós . V. Ele constituiu-o senhor de sua casa. R. E fê-lo príncipe de todos os seus bens . Oremos . Ó Deus, que por inefável providência vos dignastes escolher a São José por esposo de vossa Mãe Santíssima; concedei-nos, vo-lo pedimos, que mereçamos ter por intercessor no céu, aquele que veneramos na terra como protetor. Vós que viveis e reinais por todos os séculos dos séculos. Amém.', 'Marianas', ARRAY['#catolicoapp', '#ladainhas'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Oração de Santa Rita de Cássia', 'Ó Poderosa e gloriosa Santa Rita, eis a vossos pés uma alma desamparada que, necessitando de auxílio, a vós recorre com a doce esperança de ser atendida por vós, que tem o título de Santa dos Casos Impossíveis e Desesperados. Ó cara santa interessai-vos pela minha causa, intercedei junto a Deus para que me conceda a graça que tanto necessito (faça o pedido) . Não permitais que tenha de me afastar de vossos pés sem ser atendido. Se houver em mim algum obstáculo que me impeça de alcançar a graça que imploro, auxiliai-me para que o afaste. Envolvei o meu pedido em vossos preciosos méritos e apresentai-o a vosso celeste esposo, Jesus , em união com a vossa prece. Ó Santa Rita, eu ponho em vós toda a minha confiança. Por vosso intermédio, espero tranquilamente a graça que vos peço. Santa Rita, Advogada dos Impossíveis, rogai por nós.', 'Santos', ARRAY['#catolicoapp', '#intercessao-dos-santos'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Oração para o período Sede Vacante', 'Suplicamos, ó Deus, com humildade: que vossa imensa piedade conceda à Sacrossanta Igreja Romana um Pontífice; que por seu zelo por nós, possa ser agradável a Vós, que seja assíduo no Governo da Igreja para a glória e reverência do Vosso nome. Por nosso Senhor Jesus Cristo, vosso Filho, na Unidade do Espírito Santo, Deus, por todos os séculos dos séculos. Amém.', 'Diárias', ARRAY['#catolicoapp', '#diversas'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, 'Súpplici, Dómine, humilitate depóscimus: ut sacrosánctae Romána Ecclésia concédat Pontíficem illum tua imménsa pietas; qui et pio in nos stúdio semper tibi plácitus, et tuo pópulo pro salúbri regimine sit assídue ad glóriam tui nóminis reveréndus. Per Dóminum nostrum lesum Christum Filium tuum, qui tecum vivit et regnat in unitáte Spiritus Sancti, Deus, per ómnia sacula sæculórum. Amen.', NULL, false),
('Oração de São Bento', 'A Cruz sagrada seja minha Luz Não seja o Dragão meu guia Retira-te Satanás Nunca me aconse-lhes coisas vãs É mal o que tu me ofereces Bebe tu mesmo do teu veneno', 'Santos', ARRAY['#catolicoapp', '#intercessao-dos-santos'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Ladainha de Santo Antônio', 'Senhor, tende piedade de nós . Jesus Cristo, tende piedade de nós . Senhor, tende piedade de nós. Jesus , ouvi-nos. Jesus, atendei-nos. Pai celeste, que sois Deus, tende piedade de nós. Filho, Redentor do mundo, que sois Deus, Espírito Santo, que sois Deus, Santíssima Trindade, que sois um só Deus, Santo Antônio de Pádua, rogai por nós. Íntimo amigo do menino Deus, Servo da Mãe Imaculada, Fiel filho de São Francisco, Homem da santa oração, Amigo da pobreza, Lírio da castidade, Modelo da obediência, Amante da vida oculta, Desprezador das glórias humanas, Rosa da caridade, Espelho de todas as virtudes, Sacerdote segundo o Coração do Altíssimo, Imitador dos apóstolos, Mártir do desejo, Coluna da Igreja, Zeloso Amante das almas, Propugnador da Fé, Doutor da verdade, Batalhador contra a falsidade, Arca do testamento, Trombeta do Evangelho, Convertedor de pecadores, Extirpador de crimes, Restaurador da paz, Reformador dos costumes, Triunfador dos corações, Auxiliador dos aflitos, Terror dos demônios Ressuscitador dos mortos, Restituidor das coisas perdidas, Glorioso taumaturgo, Santo do mundo inteiro, Glória da Ordem dos Menores, Alegria da corte celeste, Nosso amável Padroeiro, Cordeiro de Deus, que tirais o pecado do mundo, perdoai-nos, Senhor. Cordeiro de Deus, que tirais o pecado do mundo, ouvi-nos, Senhor. Cordeiro de Deus, que tirais o pecado do mundo, tende piedade de nós. Rogai por nós , Santo Antônio. Para que sejamos dignos das Promessas de Cristo. OREMOS: Alegre, Senhor Deus, a vossa Igreja a solenidade votiva de Santo Antônio, vosso confessor e doutor, para que sempre se ache fortalecida com socorros espirituais e mereça alcançar os gozos eternos. Por Jesus Cristo Nosso Senhor.', 'Marianas', ARRAY['#catolicoapp', '#ladainhas'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Oração a São José para um bom trabalho', 'Glorioso São José, modelo de todos aqueles que se dedicam ao trabalho, obtende-me a graça de trabalhar com consciência, colocar o chamado do dever acima dos meus muitos pecados; trabalhar com gratidão e alegria, considerando uma honra empregar e desenvolver, por meio do trabalho, os dons recebidos de Deus; trabalhar com ordem, paz, prudência e paciência, nunca se rendendo ao cansaço ou às dificuldades; trabalhar, acima de tudo, com pureza de intenção, e com desapego de si mesmo, tendo sempre a morte diante dos meus olhos e o relato que devo prestar do tempo perdido, de talentos desperdiçados, do bem omitido, de vã complacência no sucesso tão fatal para a obra de Deus. Tudo por Jesus , tudo por Maria, tudo segundo o teu exemplo, Ó Patriarca José. Esse será meu lema na vida e na morte.', 'Santos', ARRAY['#catolicoapp', '#intercessao-dos-santos'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Santíssimo Breve de Roma', 'O Santíssimo Breve de Roma é uma oração antiga dos tempos do Império Romano. Nesta oração pedimos a proteção divina contra diversos males, assim como também reconhecemos os nossos erros e pecados pedindo perdão.', 'Diárias', ARRAY['#catolicoapp', '#diversas'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Ladainha do Espírito Santo', 'Senhor, tende piedade de nós. Jesus Cristo, tende piedade de nós. Divino Espírito Santo, ouvi-nos. Espírito Paráclito, atendei-nos. Deus Pai dos céus, tende piedade de nós. Deus Filho, redentor do mundo, Deus Espírito Santo, Santíssima Trindade, que sois um só Deus. Espírito da verdade, Espírito da sabedoria, Espírito da inteligência, Espírito da fortaleza, Espírito da piedade, Espírito do bom conselho, Espírito da ciência, Espírito do santo temor, Espírito da caridade, Espírito da alegria, Espírito da paz, Espírito das virtudes, Espírito de toda graça, Espírito da adoção dos filhos de Deus, Purificador das nossas almas, Santificador e guia da Igreja Católica, Distribuidor dos dons celestes, Conhecedor dos pensamentos e das intenções do coração, Doçura dos que começam a vos servir, Coroa dos perfeitos, Alegria dos anjos, Luz dos patriarcas, Inspiração dos profetas, Palavra e sabedoria dos apóstolos, Vitória doa mártires, Ciência dos confessores, Pureza das virgens, Unção de todos os santos, Sede-nos propício, perdoai-nos, Senhor. Sede-nos propício, atendei-nos, Senhor. De todo o pecado, livrai-nos, Senhor. De todas as tentações e ciladas do demônio, De toda a presunção e desesperação. Do ataque à verdade conhecida, Da inveja da graça fraterna, De toda a obstinação e impenitência, De toda a negligência e tepor do espírito, De toda a impureza da mente e do corpo, De todas as heresias e erros, De todo o mau espírito, Da morte má e eterna, Pela vossa eterna procedência do Pai e do Filho, Pela milagrosa conceição do Filho de Deus, Pela vossa descida sobre Jesus Cristo batizado, Pela vossa santa aparição na transfiguração do Senhor, Pela vossa vinda sobre os discípulos do Senhor, No dia do juízo, Ainda que pecadores, nós vos rogamos, ouví-nos. Para que nos perdoeis, Para que vos digneis vivificar e santificar todos os membros da Igreja, Para que vos digneis conceder-nos o dom da verdadeira piedade, devoção e oração, Para que vos digneis inspirar-mos sinceros afetos de misericórdia e de caridade, Para que vos digneis criar em nós um espírito novo e um coração puro, Para que vos digneis conceder-nos verdadeira paz e tranqüilidade no coração, Para que vos digneis fazer-nos dignos e fortes, para suportar as perseguições pela justiça, Para que vos digneis confirmar-nos em vossa graça, Para que vos digneis receber-nos o número dos vossos eleitos, Para que vos digneis ouvir-nos, Espírito de Deus, Cordeiro de Deus que tirais os pecados do mundo, envia-nos o Espírito Santo. Cordeiro de Deus que tirais os pecados do mundo, mandai-nos o Espírito prometido do Pai. Cordeiro de Deus que tirais os pecados do mundo, dai-nos o Espírito bom. Espírito Santo, ouví-nos. Espírito Consolador, atendei-nos. V. Enviai o vosso Espírito e tudo será criado. R. E renovareis a face da terra. Oremos: Deus, que instruístes o coração de vossos fiéis, com a luz do Espírito Santo, concedei-mos que, no mesmo Espírito, conheçamos o que é reto, e gozemos sempre as suas consolações. Por Cristo, Nosso Senhor. Amém.', 'Marianas', ARRAY['#catolicoapp', '#ladainhas'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Ladainha do Sagrado Coração de Jesus', 'Senhor, tende piedade de nós. Jesus Cristo, tende piedade de nós. Senhor, tende piedade de nós. Jesus Cristo, ouvi-nos. Jesus Cristo, atendei-nos. Pai celeste que sois Deus, tende piedade de nós. Filho, Redentor do mundo, que sois Deus, tende piedade de nós. Espírito Santo, que sois Deus, tende piedade de nós. Santíssima Trindade, que sois um só Deus, tende piedade de nós. Coração de Jesus, Filho do Pai Eterno, tende piedade de nós. Coração de Jesus, formado pelo Espírito Santo no seio da Virgem Mãe, Coração de Jesus, unido substancialmente ao Verbo de Deus, Coração de Jesus, de majestade infinita, Coração de Jesus, templo santo de Deus, Coração de Jesus, tabernáculo do Altíssimo, Coração de Jesus, casa de Deus e porta do céu, Coração de Jesus, fornalha ardente de caridade, Coração de Jesus, receptáculo de justiça e de amor, Coração de Jesus, cheio de bondade e de amor, Coração de Jesus, abismo de todas as virtudes, Coração de Jesus, digníssimo de todo o louvor, Coração de Jesus, Rei e centro de todos os corações, Coração de Jesus, no qual estão todos os tesouros da sabedoria e ciência, Coração de Jesus, no qual habita toda a plenitude da divindade, Coração de Jesus, no qual o Pai põe as suas complacências, Coração de Jesus, de cuja plenitude nós todos participamos, Coração de Jesus, desejo das colinas eternas, Coração de Jesus, paciente e misericordioso, Coração de Jesus, rico para todos os que vos invocam, Coração de Jesus, fonte de vida e santidade, Coração de Jesus, propiciação pelos nossos pecados, Coração de Jesus, saturado de opróbrios, Coração de Jesus, atribulado por causa de nossos crimes, Coração de Jesus, feito obediente até à morte, Coração de Jesus, atravessado pela lança, Coração de Jesus, fonte de toda a consolação, Coração de Jesus, nossa vida e ressurreição, Coração de Jesus, nossa paz e reconciliação, Coração de Jesus, vítima dos pecadores, Coração de Jesus, salvação dos que esperam em vós, Coração de Jesus, esperança dos que expiram em vós, Coração de Jesus, delícia de todos os santos, Cordeiro de Deus, que tirais os pecados do mundo, perdoai-nos Senhor. Cordeiro de Deus, que tirais os pecados do mundo, ouvi-nos Senhor. Cordeiro de Deus, que tirais os pecados do mundo, tende piedade de nós. V. Jesus, manso e humilde de coração, R. Fazei nosso coração semelhante ao vosso. Oremos: Deus onipotente e eterno, olhai para o Coração de vosso Filho diletíssimo e para os louvores e as satisfações que ele, em nome dos pecadores vos tributa; e aos que imploram a vossa misericórdia concedei benigno o perdão em nome do vosso mesmo Filho Jesus Cristo, que convosco vive e reina por todos os séculos dos séculos. Amém.', 'Marianas', ARRAY['#catolicoapp', '#ladainhas'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Ato de Contrição', 'Oração do Ato de Contrição Meu Deus, eu me arrependo, de todo coração de todos meus pecados e os detesto, porque pecando não só mereci as penas que justamente estabelecestes, mas principalmente porque Vos ofendi a Vós, sumo bem e digno de ser amado sobre todas as coisas. Por isso, proponho firmemente, com a ajuda da vossa graça, não mais pecar e fugir das ocasiões próximas de pecar. Amém Ato de Contrição para Crianças (pequeno) Meu Deus, eu me arrependo de todo meu coração de vos ter ofendido, porque sois bom e amável. Prometo, com a vossa graça, não mais pecar. Meu Jesus , misericórdia. Amém Ato de Contrição Tradicional (versão antiga) Meu Senhor Jesus Cristo, Deus e homem verdadeiro, Criador, Pai e Redentor meu. Por ser vós quem sois e porque vos amo sobre todas as coisas, pesa-me de todo o meu coração de vos ter ofendido, proponho firmemente a emenda de minha vida para nunca mais pecar, apartar-me de todas ocasiões de ofender-vos, confessar-me e cumprir a penitência que me foi imposta. Vos ofereço, Senhor minha vida, obras, e trabalhos em satisfação de todos os meus pecados e assim como vos suplico, assim confio em vossa bondade e misericórdia infinitas que mos perdoareis pelos méritos de vosso preciosíssimo sangue, paixão e morte e me dareis graça para emendar-me e perseverar em vosso santo serviçoaté o fim de minha vida. Amém. Significado e Importância do Ato de Contrição A oração do Ato de Contrição é uma forma de expressar nosso profundo arrependimento pelos pecados que cometemos e buscar o perdão de Deus. É um momento de reflexão e humildade, onde reconhecemos nossas falhas e nos esforçamos para nos corrigir. Normalmente é uma oração que rezamos no momento da Confissão, como forma de demonstrar o nosso arrependimento e o compromisso de não mais voltar a pecar. Como diz a passagem bíblica de Provérbios 28,13 , “ Quem dissimula suas faltas não há de prosperar; quem as confessa e as detesta obtém misericórdia. “, o Ato de Contrição é uma oportunidade de nos purificarmos e nos aproximarmos de Deus. Fontes: Catecismo da Igreja Católica – Confissão – Livro A Contrição Perfeita (PDF)', 'Diárias', ARRAY['#catolicoapp', '#comuns'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Oração Eucarística IX', 'PE: O Senhor esteja convosco. T: Ele está no meio de nós. PE: Corações ao alto. T: O nosso coração está em Deus. PE: Demos graças ao Senhor, nosso Deus. T: É nosso dever e nossa salvação. PE: Deus nosso Pai, vós nos reunistes e aqui estamos todos juntos, para celebrar vossos louvores com o coração em festa. Nós vos louvamos por todas as coisas bonitas que existem no mundo e também pela alegria que dais a todos nós. Nós vos louvamos pela luz do dia e por vossa palavra que é nossa luz. Nós vos louvamos pela terra onde moram todas as pessoas. Obrigado pela vida que de vós recebemos. T: O céu e a terra proclamam a vossa glória! Hosana nas alturas! PE: Sim, ó Pai, vós sois muito bom: amais a todos nós e fazeis por nós coisas maravilhosas. Vós sempre pensais em todos e quereis ficar perto de nós. Mandastes vosso filho querido para viver no meio de nós. Jesus veio para nos salvar: curou os doentes, perdoou os pecadores. Mostrou a todos o vosso amor, ó Pai; acolheu e abençoou as crianças. T: Bendito o que vem em nome do Senhor. Hosana nas alturas! PE: Nós não estamos sozinhos para cantar vossos louvores. Estamos bem unidos com a Igreja inteira: com o papa N., com o nosso bispo N. e com todos os nossos irmãos. T: Bendito o que vem em nome do Senhor. Hosana nas alturas! PE: No céu também, ó Pai, todos cantam o vosso louvor: Maria, mãe de Jesus, os apóstolos, os anjos e os santos, vossos amigos. Nós, aqui na terra, unidos a eles, com todas as crianças do mundo e suas famílias, alegres cantamos (dizemos) a uma só voz: T: Santo, santo, santo, Senhor, Deus do universo! Hosana nas alturas! PE: Pai, para vos dizer muito obrigado, trouxemos este pão e este vinho: pedimos que mandeis vosso Espírito Santo para que estas nossas ofertas se tornem o Corpo e o Sangue de Jesus, vosso Filho querido. Assim, ó Pai, vos oferecemos o mesmo dom que vós nos dais. T: Bendito sejais, Senhor Jesus! PE: Jesus, antes de sua morte, pôs-se à mesa com os apóstolos, tomou o pão nas mãos e, rezando, deu graças. Depois partiu o pão e o deu a seus amigos, dizendo: TOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS. T: Bendito sejais, Senhor Jesus! PE: Antes de terminar a ceia, Jesus pegou o cálice de vinho e agradeceu de novo. Depois o deu a seus amigos, dizendo: TOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS, PARA A REMISSÃO DOS PECADOS. E disse também: FAZEI ISTO EM MEMÓRIA DE MIM. T: Bendito sejais, Senhor Jesus! PE: Nesta reunião fazemos o que Jesus mandou. Lembramos a morte e ressurreição de Jesus que vive no meio de nós. Oferecemos, também, este pão que dá a vida e este cálice da nossa salvação. Junto com Jesus, ó Pai, entregamos a nossa vida em vossas mãos. T: Com Jesus, recebei nossa vida! PE: Pai que tanto nos amais, deixai-nos aproximar desta mesa para receber o Corpo e o Sangue do vosso Filho. Pedimos que o Espírito Santo nos ajude a viver unidos na alegria. Ó Pai, sabemos que sempre vos lembrais de todos. Por isso, pedimos por aqueles que nós amamos (N. N.) e por todos os que morreram em vossa paz. Cuidai dos que sofrem e andam tristes; olhai com carinho o povo cristão e todas as pessoas do mundo. T: Com Jesus, recebei nossa vida! PE: Diante de tudo o que fazeis por meio de vosso Filho, Jesus, nós vos bendizemos e louvamos. Por Cristo, com Cristo, em Cristo, a vós, Deus Pai todo poderoso, na unidade do Espírito Santo, toda a honra e toda a glória, agora e para sempre. T: Amém! Fonte: Missal, página 1.025', 'Diárias', ARRAY['#catolicoapp', '#oracao-eucaristica'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Oração Eucarística VIII', 'PE: O Senhor esteja convosco. T: Ele está no meio de nós. PE: Corações ao alto. T: O nosso coração está em Deus. PE: Demos graças ao Senhor, nosso Deus. T: É nosso dever e nossa salvação. PE: Nós vos agradecemos, Deus Pai todo-poderoso, e por causa de vossa ação no mundo vos louvamos pelo Senhor Jesus . No meio da humanidade, dividida em contínua discórdia, sabemos por experiência que sempre levais as pessoas a procurar a reconciliação. Vosso Espírito Santo move os corações, de modo que os inimigos voltem à amizade, os adversários se deem as mãos e os povos procurem reencontrar a paz. T: Fazei-nos, ó Pai, instrumentos de vossa Paz! PE: Sim, ó Pai, porque é obra vossa que a busca da paz vença os conflitos, que o perdão supere o ódio e vingança dê lugar à reconciliação. Por tudo de bom que fazeis, Deus de misericórdia, não podemos deixar de vos louvar e agradecer. Unidos ao coro dos reconciliados, cantamos (dizemos) a uma só voz: T: Santo, santo, santo… PE: Deus de amor e de poder, louvado sois em vosso Filho, Jesus Cristo, que veio em vosso nome. Ele é a vossa palavra que liberta e salva toda a humanidade. Ele é a mão que estendeis aos pecadores. Ele é o caminho pelo qual nos chega a vossa paz T: Fazei-nos, ó Pai, instrumentos de vossa paz! PE: Deus, nosso Pai, quando vos abandonamos, vós nos reconduzistes por vosso Filho, entregando-o à morte para que voltássemos a vós e nos amássemos uns aos outros. Por isso, celebramos a reconciliação que vosso filho nos mereceu. Cumprindo o que ele nos mandou, vos pedimos: santificai, † por vosso Espírito, estas oferendas. Antes de dar a vida para nos libertar, durante a última ceia, Jesus tomou o pão, pronunciou a bênção de ação de graças e o entregou a seus discípulos, dizendo: TOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS. Naquela mesma noite, tomou nas mãos o cálice e, proclamando a vossa misericórdia, o deu a seus discípulos, dizendo: TOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS, PARA A REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM. Eis o mistério da fé! T: Anunciamos, Senhor, a vossa morte e proclamamos a vossa ressurreição. Vinde, Senhor Jesus! PE: Ó Deus, Pai de misericórdia, vosso filho nos deixou esta prova de amor. Celebrando a sua morte e ressurreição, nós vos damos aquilo que nos destes: o sacrifício da perfeita reconciliação. T: Glória e louvor ao Pai, que em Cristo nos reconciliou! PE: Nós vos pedimos, ó Pai, aceita-nos também com vosso Filho e, nesta ceia, dai-nos o mesmo Espírito, de reconciliação e de paz. T: Glória e louvor ao Pai, que em Cristo nos reconciliou! PE: Ele nos conserve em comunhão com o papa N. e o nosso bispo N., com todos os bispos e o povo que conquistastes. Fazei de vossa Igreja sinal da unidade entre os seres humanos e instrumento da vossa paz! T: Glória e louvor ao Pai, que em Cristo nos reconciliou! PE: Assim como aqui nos reunistes, ó Pai, à mesa do vosso Filho em união com a virgem Maria, mãe de Deus, e com todos os santos, reuni no mundo novo, onde brilha a vossa paz, os homens e as mulheres de todas as classes e nações, de todas as raças e línguas, para a ceia da comunhão eterna, por Jesus Cristo, nosso Senhor. T: Glória e louvor ao Pai, que em Cristo nos reconciliou! PE: Por Cristo, com Cristo, em Cristo, a vós, Deus Pai todo poderoso, na unidade do Espírito Santo, toda a honra e toda a glória, agora e para sempre. T: Amém! Fonte: Missal, página 871', 'Diárias', ARRAY['#catolicoapp', '#oracao-eucaristica'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Oração Eucarística VII', 'PE: O Senhor esteja convosco. T: Ele está no meio de nós. PE: Corações ao alto. T: O nosso coração está em Deus. PE: Demos graças ao Senhor, nosso Deus. T: É nosso dever e nossa salvação. PE: Na verdade, é justo e bom agradecer-vos, Deus Pai, porque constantemente nos chamais a viver na felicidade completa. Vós, Deus de ternura e de bondade, nunca vos cansais de perdoar. Ofereceis vosso perdão a todos, convidando os pecadores a entregar-se confiantes à vossa misericórdia. T: Como é grande, ó Pai, a vossa misericórdia! PE: Jamais nos rejeitastes, quando quebramos a vossa aliança, mas, por Jesus , vosso Filho e nosso irmão, criastes com a família humana novo laço de amizade, tão estreito e forte, que nada poderá romper. Concedeis agora a vosso povo tempo de graça e reconciliação. Daí, pois, em Cristo, novo alento à vossa Igreja, para que se volte para vós. Fazei que, sempre mais dócil ao Espírito Santo, se coloque ao serviço de todos. T: Como é grande, ó Pai, a vossa misericórdia! PE: Cheios de admiração e reconhecimento, unimos nossa voz à voz das multidões do céu para cantar o poder de vosso amor e alegria da nossa salvação: T: Santo, santo, santo… PE: Ó Deus, desde a criação do mundo, fazeis o bem a cada um de nós para sermos santos como vós sois santo. Olhai vosso povo aqui reunido e derramai a força do Espírito, para que estas oferendas se tornem o Corpo e o Sangue do Filho muito amado, no qual também somos vossos filhos. Enquanto estávamos perdidos e incapazes de vos encontrar, vós nos amastes de modo admirável, pois vosso filho – o justo e santo – entregou-se em nossas mãos, aceitando ser pregado na cruz. T: Como é grande, ó Pai, a vossa misericórdia! PE: Antes, porém, de seus braços abertos traçarem entre o céu e a terra o sinal permanente da vossa aliança, Jesus quis celebrar a Páscoa com seus discípulos. Ceando com eles, tomou o pão e pronunciou a bênção de ação de graças. Depois, partindo o pão, o deu a seus amigos, dizendo: TOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS. Ao fim da ceia, Jesus, sabendo que ia reconciliar todas as coisas pelo sangue a ser derramado na cruz, tomou o cálice com vinho. Deu graças novamente e passou o cálice a seus amigos, dizendo: TOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS, PARA A REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM. Eis o mistério da fé! T: Anunciamos, Senhor, a vossa morte e proclamamos a vossa ressurreição. Vinde, Senhor Jesus! PE: Lembramo-nos de Jesus Cristo, nossa páscoa e certeza da paz definitiva. Hoje celebramos sua morte e ressurreição, esperando o dia feliz de sua vinda gloriosa. Por isso, vos apresentamos, ó Deus fiel, a vítima de reconciliação que nos faz voltar à vossa graça. T: Esperamos, ó Cristo, vossa vinda gloriosa! PE: Olhai com amor, Pai misericordioso, aqueles que atraís para vós, fazendo-os participar no único sacrifício de Cristo. Pela força do Espírito Santo, todos se tornem um só corpo bem unido, no qual todas as divisões sejam superadas. T: Esperamos, ó Cristo, vossa vinda gloriosa! PE: Conservai-nos, em comunhão de fé e amor, unidos ao papa N. e ao nosso bispo N.. Ajudai-nos a trabalhar juntos na construção do vosso reino, até o dia em que, diante de vós, formos santos com os vossos santos, ao lado da virgem Maria e dos apóstolos, com nossos irmãos e irmãs já falecidos que confiamos à vossa misericórdia. Quando fizermos parte da nova criação, enfim libertada de toda maldade e fraqueza, poderemos cantar a ação de graças de Cristo que vive para sempre. T: Esperamos, ó Cristo, vossa vinda gloriosa! PE: Por Cristo, com Cristo, em Cristo, a vós, Deus Pai todo poderoso, na unidade do Espírito Santo, toda a honra e toda a glória, agora e para sempre. T: Amém! Fonte: Missal, página 866', 'Diárias', ARRAY['#catolicoapp', '#oracao-eucaristica'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Oração Eucarística VI-D', 'PE: O Senhor esteja convosco. T: Ele está no meio de nós. PE: Corações ao alto. T: O nosso coração está em Deus. PE: Demos graças ao Senhor, nosso Deus. T: É nosso dever e nossa salvação. PE: Na verdade, é justo e necessário, é nosso dever e salvação dar-vos graças, sempre e em todo lugar, Pai misericordioso e Deus fiel. Vós nos destes vosso filho, Jesus Cristo, nosso Senhor e redentor. Ele sempre se mostrou cheio de misericórdia pelos pequenos e pobres, pelos doentes e pecadores, colocando-se ao lado dos perseguidos e marginalizados. Com a vida e a palavra anunciou ao mundo que sois Pai e cuidais de todos como filhos e filhas. Por essa razão, com todos os anjos e santos, nos vos louvamos e bendizemos, e proclamamos o hino de vossa glória, cantando (dizendo) a uma só voz: T: Santo, santo, santo… PE: Na verdade, vós sois santo e digno de louvor, ó Deus, que amais os seres humanos e sempre os assistis no caminho da vida. Na verdade, é bendito o vosso filho, presente no meio de nós, quando nos reunimos por seu amor. Como outrora aos discípulos, ele nos revela as Escrituras e parte o pão para nós. T: O vosso filho permaneça entre nós! PE: Nós vos suplicamos, Pai de bondade, que envieis o vosso Espírito Santo para santificar estes dons do pão e do vinho, a fim de que se tornem para nós o Corpo † e o Sangue de nosso Senhor Jesus Cristo. T: Mandai o vosso Espírito Santo! PE: Na véspera de sua paixão, durante a última ceia, ele tomou o pão, deu graças, e o partiu e deu a seus discípulos, dizendo: TOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS. Do mesmo modo, ao fim da ceia, ele, tomando o cálice em suas mãos, deu graças novamente e o entregou a seus discípulos, dizendo: TOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS, PARA A REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM. Eis o mistério da fé! T: Anunciamos, Senhor, a vossa morte e proclamamos a vossa ressurreição. Vinde, Senhor Jesus! PE: Celebrando, pois, ó Pai santo, a memória de Cristo, vosso filho, nosso salvador, que pela paixão e morte de cruz fizestes entrar na glória da ressurreição e colocastes à vossa direita, anunciamos a obra do vosso amor até que ele venha e vos oferecemos o pão da vida e o cálice da bênção. Olhai com bondade para a oferta da vossa Igreja. Nela vos apresentamos o sacrifício pascal de Cristo, que vos foi entregue. E concedei que, pela força do Espírito do vosso amor, sejamos contados, agora e por toda a eternidade, entre os membros do vosso filho, cujo Corpo e Sangue comungamos. T: Aceitai, ó Senhor, a nossa oferta! PE: Senhor Deus, conduzi a vossa Igreja à perfeição na fé e no amor, em comunhão com o nosso papa N., o nosso bispo N., com todos os bispos, presbíteros e diáconos e todo o povo que conquistastes. T: Confirmai o vosso povo na unidade! PE: Dai-nos olhos para ver as necessidades e os sofrimentos dos nossos irmãos e irmãs; inspirai-nos palavras e ações para confortar os desanimados e oprimidos; fazei que, a exemplo de Cristo e seguindo o seu mandamento, nos empenhemos lealmente no serviço a eles. Vossa Igreja seja testemunha viva da verdade e da liberdade, da justiça e da paz, para que toda a humanidade se abra à esperança de um mundo novo. T: Ajudai-nos a criar um mundo novo! PE: Lembrai-vos dos nossos irmãos e irmãs (N. e N.), que adormeceram na paz do vosso Cristo, e de todos os falecidos, cuja fé só vós conhecestes: acolhei-os na luz da vossa face e concedei-lhes, no dia da ressurreição, a plenitude da vida. T: Concedei-lhes, ó Senhor, a luz eterna! PE: Concedei-nos, ainda, no fim da nossa peregrinação terrestre, chegarmos todos à morada eterna, onde viveremos para sempre convosco. E em comunhão com a bem-aventurada virgem Maria, com os apóstolos e mártires, (com S. N.: santo do dia ou padroeiro) e todos os santos, vos louvaremos e glorificaremos, por Jesus Cristo, vosso filho. Por Cristo, com Cristo, em Cristo, a vós, Deus Pai todo poderoso, na unidade do Espírito Santo, toda a honra e toda a glória, agora e para sempre. T: Amém! Fonte: Missal, página 860', 'Diárias', ARRAY['#catolicoapp', '#oracao-eucaristica'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Oração Eucarística VI-C', 'PE: O Senhor esteja convosco. T: Ele está no meio de nós. PE: Corações ao alto. T: O nosso coração está em Deus. PE: Demos graças ao Senhor, nosso Deus. T: É nosso dever e nossa salvação. PE: Na verdade, é justo e necessário, é nosso dever e salvação, dar-vos graças, sempre e em todo lugar, Pai santo, Senhor do céu e da terra, por Cristo, Senhor nosso. Pela vossa palavra criastes o universo e em vossa justiça tudo governais. Tendo-se encarnado, vós nos destes o vosso Filho como mediador. Ele nos dirigiu a vossa palavra, convidando-nos a seguir seus passos. Ele é o caminho que conduz para vós, a verdade que nos liberta e ávida que nos enche de alegria. Por vosso filho, reunis em uma só família os homens e as mulheres criados para a glória de vosso nome, reunidos pelo sangue de sua cruz e marcados com o selo do vosso Espírito. Por essa razão, agora e sempre, nós nos unimos à multidão dos anjos e dos santos, cantando (dizendo) a uma só voz: T: Santo, santo, santo… PE: Na verdade, vós sois santo e digno de louvor, ó Deus, que amais os seres humanos e sempre os assistis no caminho da vida. Na verdade, é bendito o vosso filho, presente no meio de nós, quando nos reunimos por seu amor. Como outrora aos discípulos, ele nos revela as Escrituras e parte o pão para nós. T: O vosso filho permaneça entre nós! PE: Nós vos suplicamos, Pai de bondade, que envieis o vosso Espírito Santo para santificar estes dons do pão e do vinho, a fim de que se tornem para nós o Corpo † e o Sangue de nosso Senhor Jesus Cristo. T: Mandai o vosso Espírito Santo! PE: Na véspera de sua paixão, durante a última ceia, ele tomou o pão, deu graças, e o partiu e deu a seus discípulos, dizendo: TOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS. Do mesmo modo, ao fim da ceia, ele, tomando o cálice em suas mãos, deu graças novamente e o entregou a seus discípulos, dizendo: TOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS, PARA A REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM. Eis o mistério da fé! T: Anunciamos, Senhor, a vossa morte e proclamamos a vossa ressurreição. Vinde, Senhor Jesus! PE: Celebrando, pois, ó Pai santo, a memória de Cristo, vosso filho, nosso salvador, que pela paixão e morte de cruz fizestes entrar na glória da ressurreição e colocastes à vossa direita, anunciamos a obra do vosso amor até que ele venha e vos oferecemos o pão da vida e o cálice da bênção. Olhai com bondade para a oferta da vossa Igreja. Nela vos apresentamos o sacrifício pascal de Cristo, que vos foi entregue. E concedei que, pela força do Espírito do vosso amor, sejamos contados, agora e por toda a eternidade, entre os membros do vosso filho, cujo Corpo e Sangue comungamos. T: Aceitai, ó Senhor, a nossa oferta! PE: Pela participação neste mistério, ó Pai todo-poderoso, santificai-nos pelo Espírito e concedei que nos tornemos semelhantes à imagem de vosso filho. Fortalecei-nos na unidade, em comunhão com o nosso papa N. e o nosso bispo N., com todos os bispos, presbíteros e diáconos e todo o vosso povo. T: O vosso Espírito nos una num só corpo! PE: Fazei que todos os membros da Igreja, à luz da fé, saibam reconhecer os sinais dos tempos e empenhe-se, de verdade, no serviço do evangelho . Tornai-nos abertos e disponíveis para todos, para que possamos partilhar as dores e as angústias, as alegrias e as esperanças, e andar juntos no caminho do vosso reino. T: Caminhamos no amor e na alegria! PE: Lembrai-vos dos nossos irmãos e irmãs (N. e N.), que adormeceram na paz do vosso Cristo, e de todos os falecidos, cuja fé só vós conhecestes: acolhei-os na luz da vossa face e concedei-lhes, no dia da ressurreição, a plenitude da vida. T: Concedei-lhes, ó Senhor, a luz eterna! PE: Concedei-nos, ainda, no fim da nossa peregrinação terrestre, chegarmos todos à morada eterna, onde viveremos para sempre convosco. E em comunhão com a bem-aventurada virgem Maria, com os apóstolos e mártires (com S. N.: santo do dia ou padroeiro) e todos os santos, vos louvaremos e glorificaremos, por Jesus Cristo, vosso filho. Por Cristo, com Cristo, em Cristo, a vós, Deus Pai todo poderoso, na unidade do Espírito Santo, toda a honra e toda a glória, agora e para sempre. T: Amém! Fonte: Missal, página 854', 'Diárias', ARRAY['#catolicoapp', '#oracao-eucaristica'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Oração Eucarística VI-B', 'PE: O Senhor esteja convosco. T: Ele está no meio de nós. PE: Corações ao alto. T: O nosso coração está em Deus. PE: Demos graças ao Senhor, nosso Deus. T: É nosso dever e nossa salvação. PE: Na verdade, é justo e necessário, é nosso dever e salvação dar-vos graças e cantar-vos um hino de glória e louvor, Senhor, Pai de infinita bondade. Pela palavra do evangelho do vosso Filho reunistes uma só Igreja de todos os povos, línguas e nações. Vivificada pela força do vosso Espírito, não deixais, por meio dela, de congregar na unidade todos os seres humanos. Assim, manifestando a aliança do vosso amor, a Igreja transmite constantemente a alegre esperança do vosso reino e brilha como sinal da vossa fidelidade que prometestes para sempre em Jesus Cristo, Senhor nosso. Por esta razão, com todas as virtudes do céu, nós vos celebramos na terra, cantando (dizendo) com toda a Igreja a uma só voz: T: Santo, santo, santo… PE: Na verdade, vós sois santo e digno de louvor, ó Deus, que amais os seres humanos e sempre os assistis no caminho da vida. Na verdade, é bendito o vosso Filho, presente no meio de nós, quando nos reunimos por seu amor. Como outrora aos discípulos, ele nos revela as Escrituras e parte o pão para nós. T: O vosso Filho permaneça entre nós! PE: Nós vos suplicamos, Pai de bondade, que envieis o vosso Espírito Santo para santificar estes dons do pão e do vinho, a fim de que se tornem para nós o Corpo e † o Sangue de nosso Senhor Jesus Cristo. T: Mandai o vosso Espírito Santo! PE: Na véspera de sua paixão, durante a última ceia, ele tomou o pão, deu graças e o partiu e deu a seus discípulos, dizendo: TOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS. Do mesmo modo, ao fim da ceia, ele tomou o cálice em suas mãos, deu graças novamente e o entregou a seus discípulos, dizendo: TOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS, PARA A REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM. Eis o mistério da fé! T: Salvador do mundo, salvai-nos, vós que nos libertastes pela cruz e ressurreição! PE: Celebrando, pois, ó Pai santo, a memória de Cristo, vosso Filho, nosso salvador, que pela paixão e morte de cruz fizestes entrar na glória da ressurreição e colocastes à vossa direita, anunciamos a obra do vosso amor até que ele venha e vos oferecemos o pão da vida e o cálice da bênção. Olhai com bondade para a oferta da vossa Igreja. Nela vos apresentamos o sacrifício pascal de Cristo, que vos foi entregue. E concedei que, pela força do Espírito do vosso amor, sejamos contados, agora e por toda a eternidade, entre os membros do vosso Filho, cujo Corpo e Sangue comungamos. T: Aceitai, ó Senhor, a nossa oferta! PE: Renovai, Senhor, à luz do evangelho, a vossa Igreja (que está em N…). Fortalecei o vínculo da unidade entre os fiéis leigos e os pastores do vosso povo, em comunhão com o nosso papa N. e o nosso bispo N. e os bispos do mundo inteiro, para que o vosso povo, neste mundo dilacerado por discórdias, brilhe como sinal profético de unidade e de paz. T: Confirmai na caridade o vosso povo! PE: Lembrai-vos dos nossos irmãos e irmãs (N. e N.), que adormeceram na paz do vosso Cristo, e de todos os falecidos, cuja fé só vós conhecestes: acolhei-os na luz da vossa face e concedei-lhes, no dia da ressurreição, a plenitude da vida. T: Concedei-lhes, ó Senhor, a luz eterna! PE: Concedei-nos ainda, no fim da nossa peregrinação terrestre, chegarmos todos à morada eterna, onde viveremos para sempre convosco. E em comunhão com a bem-aventurada virgem Maria, com os apóstolos e mártires (com S. N.: santo do dia ou padroeiro) e todos os santos, vos louvaremos e glorificaremos, por Jesus Cristo, vosso Filho. Por Cristo, com Cristo, em Cristo, a vós, Deus Pai todo poderoso, na unidade do Espírito Santo, toda a honra e toda a glória, agora e para sempre. T: Amém! Fonte: Missal, página 848', 'Diárias', ARRAY['#catolicoapp', '#oracao-eucaristica'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Oração Eucarística VI-A', 'PE: O Senhor esteja convosco. T: Ele está no meio de nós. PE: Corações ao alto. T: O nosso coração está em Deus. PE: Demos graças ao Senhor, nosso Deus. T: É nosso dever e nossa salvação. PE: Na verdade, é justo e necessário, é nosso dever e salvação dar-vos graças e cantar-vos um hino de glória e louvor, Senhor, Pai de infinita bondade. Pela palavra do evangelho do vosso Filho reunistes uma só Igreja de todos os povos, línguas e nações. Vivificada pela força do vosso Espírito, não deixais, por meio dela, de congregar na unidade todos os seres humanos. Assim, manifestando a aliança do vosso amor, a Igreja transmite constantemente a alegre esperança do vosso reino e brilha como sinal da vossa fidelidade que prometestes para sempre em Jesus Cristo, Senhor nosso. Por esta razão, com todas as virtudes do céu, nós vos celebramos na terra, cantando (dizendo) com toda a Igreja a uma só voz: T: Santo, santo, santo… PE: Na verdade, vós sois santo e digno de louvor, ó Deus, que amais os seres humanos e sempre os assistis no caminho da vida. Na verdade, é bendito o vosso Filho, presente no meio de nós, quando nos reunimos por seu amor. Como outrora aos discípulos, ele nos revela as Escrituras e parte o pão para nós. T: O vosso Filho permaneça entre nós! PE: Nós vos suplicamos, Pai de bondade, que envieis o vosso Espírito Santo para santificar estes dons do pão e do vinho, a fim de que se tornem para nós o Corpo e † o Sangue de nosso Senhor Jesus Cristo. T: Mandai o vosso Espírito Santo! PE: Na véspera de sua paixão, durante a última ceia, ele tomou o pão, deu graças e o partiu e deu a seus discípulos, dizendo: TOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS. Do mesmo modo, ao fim da ceia, ele tomou o cálice em suas mãos, deu graças novamente e o entregou a seus discípulos, dizendo: TOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS, PARA A REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM. Eis o mistério da fé! T: Salvador do mundo, salvai-nos, vós que nos libertastes pela cruz e ressurreição! PE: Celebrando, pois, ó Pai santo, a memória de Cristo, vosso Filho, nosso salvador, que pela paixão e morte de cruz fizestes entrar na glória da ressurreição e colocastes à vossa direita, anunciamos a obra do vosso amor até que ele venha e vos oferecemos o pão da vida e o cálice da bênção. Olhai com bondade para a oferta da vossa Igreja. Nela vos apresentamos o sacrifício pascal de Cristo, que vos foi entregue. E concedei que, pela força do Espírito do vosso amor, sejamos contados, agora e por toda a eternidade, entre os membros do vosso Filho, cujo Corpo e Sangue comungamos. T: Aceitai, ó Senhor, a nossa oferta! PE: Renovai, Senhor, à luz do evangelho, a vossa Igreja (que está em N…). Fortalecei o vínculo da unidade entre os fiéis leigos e os pastores do vosso povo, em comunhão com o nosso papa N. e o nosso bispo N. e os bispos do mundo inteiro, para que o vosso povo, neste mundo dilacerado por discórdias, brilhe como sinal profético de unidade e de paz. T: Confirmai na caridade o vosso povo! PE: Lembrai-vos dos nossos irmãos e irmãs (N. e N.), que adormeceram na paz do vosso Cristo, e de todos os falecidos, cuja fé só vós conhecestes: acolhei-os na luz da vossa face e concedei-lhes, no dia da ressurreição, a plenitude da vida. T: Concedei-lhes, ó Senhor, a luz eterna! PE: Concedei-nos ainda, no fim da nossa peregrinação terrestre, chegarmos todos à morada eterna, onde viveremos para sempre convosco. E em comunhão com a bem-aventurada virgem Maria, com os apóstolos e mártires (com S. N.: santo do dia ou padroeiro) e todos os santos, vos louvaremos e glorificaremos, por Jesus Cristo, vosso Filho. Por Cristo, com Cristo, em Cristo, a vós, Deus Pai todo poderoso, na unidade do Espírito Santo, toda a honra e toda a glória, agora e para sempre. T: Amém! Fonte: Missal, página 842', 'Diárias', ARRAY['#catolicoapp', '#oracao-eucaristica'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Oração Eucarística V', 'Texto Oficial da Terceira Edição Típica do Missal Romano (Novo Missal – 1ª Edição, 2023) PR: É justo e nos faz todos ser mais santos, louvar a vós, ó Pai, no mundo inteiro, de dia e de noite, agradecendo com Cristo, vosso Filho, nosso irmão. É ele o sacerdote verdadeiro que sempre se oferece por nós todos, mandando que se faça a mesma coisa que fez naquela ceia derradeira. Por isso, aqui estamos bem unidos, louvando e agradecendo com alegria, juntando nossa voz à voz dos Anjos e dos Santos todos, para cantar (dizer): AS: Santo, Santo, Santo, Senhor Deus do universo! O céu e a terra proclamam a vossa glória. Hosana nas alturas! Bendito o que vem em nome do Senhor! Hosana nas alturas! PR: Ó Pai, vós que sempre quisestes ficar muito perto de nós, vivendo conosco no Cristo, falando conosco por ele, mandai o vosso Espírito Santo, a fim de que as nossas ofertas se mudem no Corpo † e no Sangue de nosso Senhor Jesus Cristo. AS: Mandai vosso Espírito Santo! PR: Na noite em que ia ser entregue, ceando com seus Apóstolos, Jesus tomou o pão em suas mãos, olhou para o céu e vos deu graças, partiu o pão e o entregou a seus discípulos, dizendo: TOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS. Do mesmo modo, no fim da Ceia, tomou o cálice em suas mãos, deu-vos graças novamente e o entregou a seus discípulos, dizendo: TOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS, PARA A REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM. Tudo isto é mistério da fé! AS: Toda vez que comemos deste Pão, toda vez que bebemos deste Vinho, recordamos a paixão de Jesus Cristo e ficamos esperando sua vinda. PR: Recordando, ó Pai, neste momento, a paixão de Jesus, nosso Senhor, sua ressurreição e ascensão, nós queremos a vós oferecer este Pão que alimenta e que dá vida, este Vinho que nos salva e dá coragem. AS: Recebei, ó Senhor, a nossa oferta! PR: E quando recebermos Pão e Vinho, o Corpo e Sangue dele oferecidos, o Espírito nos una num só corpo, para sermos um só povo em seu amor. AS: O Espírito nos uma num só corpo! PR: Protegei vossa Igreja que caminha nas estradas do mundo rumo ao céu, cada dia renovando a esperança de chegar junto a vós, na vossa paz. AS: Caminhamos na estrada de Jesus! PR: Dai ao vosso servo, o Papa N., ser bem firme na fé, na caridade, e a N., que é Bispo desta Igreja, muita luz para guiar o vosso povo. AS: Caminhamos na estrada de Jesus! PR: Esperamos entrar na vida eterna com Maria, Mãe de Deus e da Igreja, os Apóstolos, e todos os que na vida souberam amar Cristo e seus irmãos. AS: Esperamos entrar na vida eterna! PR: Abri as portas da misericórdia aos que chamastes para a outra vida; acolhei-os juntos a vós, bem felizes no reino que para todos preparastes. AS: A todos dai a luz que não se apaga! PR: E a todos nós, aqui reunidos, que somos povo santo e pecador, dai-nos a graça de participar do vosso reino que também é nosso. PR: Por Cristo, com Cristo, em Cristo, a vós, Deus Pai todo poderoso, na unidade do Espírito Santo, toda honra e toda a glória, por todos os séculos dos séculos. AS: Amém! E segue o Rito da Comunhão.', 'Diárias', ARRAY['#catolicoapp', '#oracao-eucaristica'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Oração Eucarística IV', 'Texto Oficial da Terceira Edição Típica do Missal Romano (Novo Missal – 1ª Edição, 2023) PR: Na verdade, ó Pai, é nosso dever dar-vos graças, é nossa salvação dar-vos glória. Só vós sois o Deus vivo e verdadeiro que existis antes de todo o tempo e permaneceis para sempre, habitando em luz inacessível. Mas, porque sois o Deus de bondade e a fonte da vida, fizestes todas as coisas para cobrir de bênçãos as vossas criaturas e a muitos alegrar com a vossa luz. PR: Eis, pois, diante de vós os inumeráveis coros dos Anjos que dia e noite vos servem e, contemplando a glória de vossa face, vos louvam sem cessar. Com eles também nós e, por nossa voz, tudo o que criastes celebramos o vosso Nome, e exultantes de alegria, cantamos (dizemos) a uma só voz: AS: Santo, Santo, Santo, Senhor Deus do universo! O céu e a terra proclamam a vossa glória. Hosana nas alturas! Bendito o que vem em nome do Senhor! Hosana nas alturas! PR: Nós proclamamos vossa grandeza, Pai santo, a sabedoria e o amor com que fizestes todas as coisas. Criastes o ser humano à vossa imagem e lhe confiastes todo o universo para que, servindo somente a vós, seu Criador, cuidasse de toda criatura. E quando pela desobediência perdeu a vossa amizade, não o abandonastes ao poder da morte. A todos, porém, socorrestes com misericórdia, para que, ao procurar-vos, vos encontrassem. Muitas vezes oferecestes aliança à família humana e a instruístes pelos profetas na esperança da salvação. AS: A todos socorrestes com bondade! PR: E de tal modo, Pai santo, amastes o mundo que, chegada a plenitude dos tempos, nos enviastes vosso próprio Filho para ser o nosso Salvador. Encarnado pelo poder do Espírito Santo e nascido da Virgem Maria, Jesus viveu em tudo a condição humana, menos o pecado; anunciou aos pobres a salvação, aos oprimidos, a liberdade, aos tristes, a alegria. Para cumprir o vosso plano de amor, entregou-se à morte e, ressuscitando, destruiu a morte e renovou a vida. AS: Por amor nos enviastes vosso Filho! PR: E, a fim de não mais vivermos para nós, mas para ele, que por nós morreu e ressuscitou, enviou de vós, ó Pai, como primeiro dom aos vossos fiéis, o Espírito Santo, que continua sua obra no mundo para levar à plenitude toda a santificação. PR: Por isso, nós vos pedimos, ó Pai, que o mesmo Espírito Santo santifique estas oferendas, a fim de que se tornem o Corpo † e o Sangue de Jesus Cristo, vosso Filho e Senhor nosso, para celebrarmos este grande mistério que ele nos deixou em sinal da eterna aliança. AS: Enviai o vosso Espírito Santo! PR: Quando, pois, chegou a hora em que por vós, ó Pai, ia ser glorificado, tendo amado os seus que estavam no mundo, amou-os até o fim. Enquanto ceavam, Jesus tomou o pão, pronunciou a bênção de ação de graças, partiu e o deu a seus discípulos, dizendo: TOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS. Do mesmo modo, ele tomou em suas mãos o cálice com o vinho , deu-vos graças novamente e o deu a seus discípulos, dizendo: TOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS, PRA REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM. Mistério da fé! AS: Anunciamos, Senhor, a vossa morte e proclamamos a vossa ressurreição. Vinde, Senhor Jesus! Ou: Mistério da fé e do amor! AS: Todas as vezes que comemos deste pão e bebemos deste cálice, anunciamos, Senhor, a vossa morte, enquanto esperamos a vossa vinda! Ou: Mistério da fé para a salvação do mundo! AS: Salvador do mundo, salvai-nos, vós que nos libertastes pela cruz e ressurreição. PR: Celebrando, agora, ó Pai, o memorial da nossa redenção, anunciamos a morte de Cristo e sua descida entre os mortos, proclamamos a sua ressurreição e ascensão à vossa direita e, esperando a sua vinda gloriosa, nós vos oferecemos o seu Corpo e Sangue, sacrifício do vosso agrado e salvação do mundo inteiro. AS: Aceitai, ó Senhor, a nossa oferta! PR: Olhai, com bondade, a oblação que destes à vossa Igreja e concedei aos que vamos participar do mesmo pão e do mesmo cálice que, reunidos pelo Espírito Santo num só corpo, nos tornemos em Cristo uma oferenda viva para o louvor da vossa glória. AS: O Espírito nos una num só corpo! PR: E agora, ó Pai, lembrai-vos de todos pelos quais vos oferecemos este sacrifício: o vosso servo o Papa N., o nosso Bispo N., os bispos do mundo inteiro, os presbíteros, os diáconos, e todos os ministros da vossa Igreja, os fiéis que, ao redor deste altar, se unem à nossa oferta, o povo que vos pertence e todos aqueles que vos procuram de coração sincero. AS: Lembrai-vos, ó Pai, da vossa Igreja! PR: Lembrai-vos também dos que morreram na paz do vosso Cristo e de todos os defuntos dos quais só vós conhecestes a fé. AS: Concedei-lhes, ó Senhor, a luz eterna! PR: E a todos nós, vossos Filhos e Filhas, concedei, ó Pai de bondade, alcançar a herança eterna, com a Virgem Maria, Mãe de Deus, São José, seu esposo, os Apóstolos e todos os Santos, no vosso reino, onde, com todas as criaturas, libertas da corrupção do pecado e da morte, vos glorificaremos por Cristo, Senhor nosso, por quem dais ao mundo todo bem e toda graça. PR: Por Cristo, com Cristo, e em Cristo, a vós, Deus Pai todo-poderoso, na unidade do Espírito Santo, toda a honra e toda a glória, por todos os séculos dos séculos. AS: Amém! E segue o Rito da Comunhão.', 'Diárias', ARRAY['#catolicoapp', '#oracao-eucaristica'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Oração Eucaristica III', 'Texto Oficial da Terceira Edição Típica do Missal Romano (Novo Missal – 1ª Edição, 2023) PR: Na verdade, vós sois Santo, ó Deus do universo, e tudo o que criastes proclama o vosso louvor, porque, por Jesus Cristo, vosso Filho e Senhor nosso, e pela força do Espírito Santo, dais vida e santidade a todas as coisas e não cessais de reunir para vós um povo que vos ofereça em toda parte, do nascer ao pôr do sol, um sacrifício perfeito. PR: Por isso, ó Pai, nós vos suplicamos: santificai pelo Espírito Santo as oferendas que vos apresentamos para serem consagradas a fim de que se tornem o Corpo † e o Sangue de vosso Filho, nosso Senhor Jesus Cristo, que nos mandou celebrar estes mistérios. AS: Enviai o vosso Espírito Santo! PR: Na noite em que ia ser entregue, Jesus tomou o pão, pronunciou a bênção de ação de graças, partiu e o deu a seus discípulos, dizendo: TOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS. Do mesmo modo, ao fim da Ceia, ele tomou o cálice em suas mãos, pronunciou a bênção de ação de graças, e o deu a seus discípulos, dizendo: TOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS, PARA A REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM. Mistério da fé! AS: Anunciamos, Senhor, a vossa morte e proclamamos a vossa ressurreição. Vinde, Senhor Jesus! Ou: Mistério da fé e do amor! AS: Todas as vezes que comemos deste pão e bebemos deste cálice, anunciamos, Senhor, a vossa morte, enquanto esperamos a vossa vinda! Ou: Mistério da fé para a salvação do mundo! AS: Salvador do mundo, salvai-nos, vós que nos libertastes pela cruz e ressurreição. PR: Celebrando agora, ó Pai, o memorial da paixão redentora do vosso Filho, da sua gloriosa ressurreição e ascensão ao céu, e enquanto esperamos sua nova vinda, nós vos oferecemos em ação de graças este sacrifício vivo e santo. AS: Aceitai, ó Senhor, a nossa oferta! PR: Olhai com bondade a oblação da vossa Igreja e reconhecei nela o sacrifício que nos reconciliou convosco; concedei que, alimentando-nos com o Corpo e o Sangue do vosso Filho, repletos do Espírito Santo, nos tornemos em Cristo um só corpo e um só espírito. AS: O Espírito nos una num só corpo! PR: Que o mesmo Espírito faça de nós uma eterna oferenda para alcançarmos a herança com os vossos eleitos: a santíssima Virgem Maria, Mãe de Deus, São José, seu esposo, os vossos santos Apóstolos e gloriosos Mártires, N. (Santo do dia ou padroeiro) e todos os Santos, que não cessam de interceder por nós na vossa presença. AS: Fazei de nós um perfeita oferenda! PR: Nós vos suplicamos, Senhor, que este sacrifício da nossa reconciliação estenda a paz e a salvação ao mundo inteiro. Confirmai na fé e na caridade a vossa Igreja que caminha neste mundo com o vosso servo o Papa N., e o nosso Bispo N., com os bispos do mundo inteiro, os presbíteros e diáconos, os outros ministros e o povo por vós redimido. Atendei propício às preces desta família, que reunistes em vossa presença. Reconduzi a vós, Pai de misericórdia, todos os vossos filhos e filhas dispersos pelo mundo inteiro. AS: Lembrai-vos, ó Pai, da vossa Igreja! PR: Acolhei com bondade no vosso reino os nossos irmãos e irmãs que partiram desta vida e todos os que morreram na vossa amizade. Unidos a eles, esperamos também nós saciar-nos eternamente da vossa glória, por Cristo, Senhor nosso. Por ele dais ao mundo todo bem e toda graça PR: Por Cristo, com Cristo, e em Cristo, a vós, Deus Pai todo-poderoso, na unidade do Espírito Santo, toda honra e toda glória, por todos os séculos dos séculos. AS: Amém! E segue o Rito da Comunhão.', 'Diárias', ARRAY['#catolicoapp', '#oracao-eucaristica'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Oração Eucarística II', 'Texto Oficial da Terceira Edição Típica do Missal Romano (1ª Edição, 2023) PR: Na verdade, é digno e justo, é nosso dever e salvação dar-vos graças sempre e em todo o lugar, Senhor, Pai santo, por vosso amado Filho, Jesus Cristo. Ele é a vossa Palavra, pela qual tudo criastes. Ele é o nosso Salvador e Redentor, que se encarnou pelo Espírito Santo e nasceu da Virgem Maria. Ele, para cumprir a vossa vontade e adquirir para vós um povo santo, estendeu os braços na hora da sua paixão, a fim de vencer a morte e manifestar a ressurreição. Por isso, com os Anjos e todos os Santos, proclamamos vossa glória, cantando (dizendo) a uma só voz: AS: Santo, Santo, Santo, Senhor Deus do universo! O céu e a terra proclamam a vossa glória. Hosana nas alturas! Bendito o que vem em nome do Senhor! Hosana nas alturas! PR: Na verdade, ó Pai, vós sois Santo, fonte de toda santidade. Santificai, pois, estes dons, derramando sobre eles o vosso Espírito, a fim de que se tornem para nós o Corpo e † o Sangue de nosso Jesus Cristo. AS: Enviai o Vosso Espírito Santo! PR: Estando para ser entregue e abraçando livremente a paixão, Jesus tomou o pão, pronunciou a bênção de ação de graças, partiu e o deu a seus discípulos, dizendo: TOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS. Do mesmo modo, no fim da Ceia, ele tomou o cálice em suas mãos e, dando graças novamente, o entregou a seus discípulos, dizendo: TOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS, PARA A REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM. PR: Mistério da fé! AS: Anunciamos, Senhor, a vossa morte e proclamamos a vossa ressurreição. Vinde, Senhor Jesus! Ou: PR: Mistério da fé e do amor! AS: Todas as vezes que comemos deste pão e bebemos deste cálice, anunciamos, Senhor, a vossa morte, enquanto esperamos a vossa vinda! Ou: PR: Mistério da fé para a salvação do mundo! AS: Salvador do mundo, salvai-nos, vós que nos libertastes pela cruz e ressurreição. PR: Celebrando, pois, o memorial da morte e ressurreição do vosso Filho, nós vos oferecemos, ó Pai, o Pão da vida e o Cálice da salvação; e vos agradecemos porque nos tornastes dignos de estar aqui na vossa presença e vos servir. AS: Aceitai, ó Senhor, a nossa oferta! PR: Suplicantes, vos pedimos que, participando do Corpo e Sangue de Cristo, sejamos reunidos pelo Espírito Santo num só corpo. AS: O Espírito nos una num só corpo! PR: Lembrai-vos, ó Pai, da vossa Igreja que se faz presente pelo mundo inteiro; que ela cresça na caridade, em comunhão com o papa N., com o nosso bispo N., os bispos do mundo inteiro, os presbíteros, os diáconos e todos os ministros do vosso povo. AS: Lembrai-vos, ó Pai, da vossa Igreja! Aos Domingos PR: Lembrai-vos, ó Pai, da vossa Igreja que se faz presente pelo mundo inteiro; e aqui convocada no dia em que Cristo venceu a morte e nos fez participantes de sua vida imortal; PR: Lembrai-vos do vosso filho (da vossa filha) N., que (hoje) chamastes deste mundo à vossa presença. Tendo sido sepultado (a) com Cristo em sua morte, no Batismo, participe igualmente da sua ressurreição. PR: Lembrai-vos também, na vossa misericórdia, dos (outros) nossos irmãos e irmãs que adormeceram na esperança da ressurreição e de todos os que partiram desta vida; acolhei-os junto a vós na luz da vossa face. AS: Concedei-lhes, ó Senhor, a luz eterna! PR: Enfim, nós vos pedimos, tende piedade de todos nós e dai-nos participar da vida eterna, com a Virgem Maria, Mãe de Deus, São José, seu esposo, Os Apóstolos, (São N. Santo do dia ou padroeiro) e todos os Santos que neste mundo viveram na vossa amizade, a fim de vos louvarmos e glorificarmos por Jesus Cristo, vosso Filho. PR: Por Cristo, com Cristo, e em Cristo, a vós, Deus Pai todo-poderoso, na unidade do Espírito Santo, toda a honra e toda a glória, por todos os séculos dos séculos. AS: Amém! E segue o Rito da Comunhão.', 'Diárias', ARRAY['#catolicoapp', '#oracao-eucaristica'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Oração Eucarística I', 'Texto Oficial da Terceira Edição Típica do Missal Romano (1ª Edição, 2023) PR: Pai de misericórdia, a quem sobem nossos louvores, suplicantes, vos rogamos e pedimos por Jesus Cristo, vosso Filho e Senhor nosso, que aceiteis e abençoeis † estes dons, estas oferendas, este sacrifício puro e santo, que oferecemos, antes de tudo, pela vossa Igreja santa e católica: concedei-lhe paz e proteção, unindo-a num só corpo e governando-a por toda a terra, em comunhão com o vosso servo o Papa N., o nosso Bispo N., e todos os que guardam a fé católica que receberam dos Apóstolos. AS: Abençoai nossa oferenda, ó Senhor! “memento dos vivos” PR: Lembrai-vos, ó Pai, dos vossos filhos e filhas N. N. e de todos os que circundam este altar, dos quais conheceis a fé e a dedicação ao vosso serviço. Por eles nós vos oferecemos e também eles vos oferecem este sacrifício de louvor por si e por todos os seus, e elevam a vós as suas preces, Deus eterno, vivo e verdadeiro, para alcançar o perdão de suas faltas, a segurança em suas vidas e a salvação que esperam. AS: Lembrai-vos, ó Pai, de vossos filhos! “Infra actionem” PR: Em comunhão com toda a Igreja, celebramos em primeiro lugar a memória da Mãe de nosso Deus e Senhor Jesus Cristo, a gloriosa sempre Virgem Maria, a de seu esposo São José, e também a dos Santos Apóstolos e Mártires: Pedro e Paulo, André, (Tiago e João, Tomé, Tiago e Filipe, Bartolomeu e Mateus, Simão e Tadeu, Lino, Cleto, Clemente, Sisto, Cornélio e Cipriano, Lourenço e Crisógono, João e Paulo, Cosme e Damião), e todos os vossos Santos. Por seus méritos e preces concedei-nos sem cessar a vossa proteção. (Por Cristo, nosso Senhor. Amém). AS: Em comunhão com os vossos Santos vos louvamos! “Para os Domingos” PR: Em comunhão com toda a Igreja, celebramos o glorioso dia em que o Senhor venceu a morte e nos tornou participantes de sua vida imortal. Veneramos em primeiro lugar a memória da Mãe de nosso Deus e Senhor Jesus Cristo, a gloriosa sempre Virgem Maria, “No Natal do Senhor e durante a Oitava” PR: Em comunhão com toda a Igreja, celebramos (a noite santíssima) o dia santíssimo, em que Maria, intacta em sua virgindade, deu à luz o Salvador do mundo. Veneramos em primeiro lugar a memória da mesma Mãe de nosso Deus e Senhor Jesus Cristo, a gloriosa sempre Virgem Maria, “Na Epifania do Senhor” PR: Em comunhão com toda a Igreja, celebramos o dia santíssimo, em que vosso Filho unigênito, eterno convosco na glória, se manifestou visivelmente em nossa carne. Veneramos em primeiro lugar a memória da Mãe de nosso Deus e Senhor Jesus Cristo, a gloriosa sempre Virgem Maria, “Da Vigília Pascal até o 2º domingo da Páscoa” PR: Em comunhão com toda a Igreja, celebramos (a noite santíssima) o dia santíssimo da Ressurreição de nosso Senhor Jesus Cristo segundo a carne. Veneramos em primeiro lugar a memória da Mãe de nosso Deus e Senhor Jesus Cristo, a gloriosa sempre Virgem Maria, “Na Ascensão do Senhor” PR: Em comunhão com toda a Igreja, celebramos o dia santíssimo em que Nosso Senhor, vosso Filho unigênito, elevou à vossa direita na glória a nossa frágil natureza humana. Veneramos em primeiro lugar a memória da Mãe de nosso Deus e Senhor Jesus Cristo, a gloriosa sempre Virgem Maria, “Em Pentecostes” PR: Em comunhão com toda a Igreja, celebramos o dia santíssimo de Pentecostes em que o Espírito Santo, em línguas de fogo, se manifestou aos Apóstolos. Veneramos em primeiro lugar a memória da mesma Mãe de nosso Deus e Senhor Jesus Cristo, a gloriosa sempre Virgem Maria, PR: Aceitai, ó Pai, com bondade, a oblação dos vossos servos e de toda a vossa família; dai-nos sempre a vossa paz, livrai-nos da condenação eterna e acolhei-nos entre os vossos eleitos. (Por Cristo, Senhor nosso. Amém) “Da Vigília Pascal até o 2º domingo da Páscoa” PR: Aceitai, ó Pai, com bondade, a oblação dos vossos servos e de toda a vossa família; nós a oferecemos também por aqueles que vos dignastes regenerar pela água e pelo Espírito Santo, concedendo-lhes a remissão de todos os pecados. Dai aos nossos dias a vossa paz, livrai-nos da condenação eterna e acolhei-nos entre os vossos eleitos. (Por Cristo, nosso Senhor. Amém) PR: Dignai-vos, ó Pai, aceitar, abençoar e santificar estas oferendas, recebei-as como sacrifício espiritual perfeito, a fim de que se tornem para nós o Corpo e † o Sangue de vosso amado Filho, nosso Senhor Jesus Cristo. AS: Enviai o vosso Espírito Santo! PR: Na véspera de sua paixão, ele tomou o pão em suas santas e veneráveis mãos, elevou os olhos ao céu, a vós, ó Pai, todo-poderoso, pronunciou a bênção de ação de graças, partiu o pão e o deu a seus discípulos, dizendo: TOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS. Do mesmo modo, ao fim da Ceia, ele tomou este precioso cálice em suas santas e veneráveis mãos, pronunciou novamente a bênção de ação de graças e o deu a seus discípulos, dizendo: TOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS, PRA REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM. Mistério da fé! AS: Anunciamos, Senhor, a vossa morte e proclamamos a vossa ressurreição. Vinde, Senhor Jesus! Ou: Mistério da fé e do amor! AS: Todas as vezes que comemos deste pão e bebemos deste cálice, anunciamos, Senhor, a vossa morte, enquanto esperamos a vossa vinda! Ou: Mistério da fé para a salvação do mundo! AS: Salvador do mundo, salvai-nos, vós que nos libertastes pela cruz e ressurreição. PR: Celebrando, pois, a memória da bem-aventurada paixão do vosso Filho, da sua ressurreição dentre os mortos e gloriosa ascensão aos céus, nós, vossos servos, e também vosso povo santo, vos oferecemos, ó Pai, dentre os bens que nos destes, o sacrifício puro, santo e imaculado, Pão santo da vida eterna e Cálice da perpétua salvação. PR : Recebei, ó Pai, com olhar benigno, esta oferta, como recebestes os dons do justo Abel, o sacrifício de nosso patriarca Abraão e a oblação pura e santa do sumo sacerdote Melquisedeque. AS: Aceitai, ó Senhor, a nossa oferta! PR: Suplicantes, vos pedimos, ó Deus onipotente, que esta nossa oferenda seja levada à vossa presença, no altar do céu, pelas mãos do vosso santo Anjo, para que todos nós, participando deste altar, pela comunhão do santíssimo Corpo e Sangue do vosso Filho, sejamos repletos de todas as graças e bênçãos do céu. (Por Cristo, nosso Senhor. Amém) AS: O Espírito nos una num só corpo! “memento dos mortos” PR: Lembrai-vos, ó Pai, dos vossos filhos e filhas N. N. que nos precederam com o sinal da fé e dormem o sono da paz. A eles, e a todos os que descansam no Cristo, concedei o repouso, a luz e a paz. (Por Cristo, nosso Senhor. Amém) AS: Concedei-lhes, ó Senhor, a luz eterna! PR: E a todos nós pecadores, que esperamos na vossa infinita misericórdia, concedei, não por nossos méritos, mas por vossa bondade, o convívio dos Apóstolos e Mártires: João Batista e Estêvão, Matias e Barnabé, (Inácio, Alexandre, Marcelino e Pedro, Felicidade e Perpétua, Águeda e Luzia, Inês, Cecília, Anastácia) e de todos os vossos Santos. Por Cristo, nosso Senhor. PR: Por ele não cessais de criar e santificar, vivificar, abençoar estes bens e distribuí-los entre nós. PR: Por Cristo, com Cristo, e em Cristo, a vós, Deus Pai todo-poderoso, na unidade do Espírito Santo, toda a honra e toda a glória, por todos os séculos dos séculos. AS: Amém. Segue-se o Rito da Comunhão.', 'Diárias', ARRAY['#catolicoapp', '#oracao-eucaristica'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Oração a São Vicente de Paulo', 'Glorioso São Vicente, celeste padroeiro de todas as associações de caridade e pai de todos os infelizes que, enquanto vivestes sobre a terra, nunca faltastes àqueles que se valeram de vossa proteção; vede a multidão de males de que estamos oprimidos e correi em nosso auxílio; alcançai do Senhor socorro para os pobres, auxilio aos enfermos, consolação aos aflitos, proteção aos desamparados, conversão aos pecadores, zelo aos sacerdotes, paz à Igreja, tranqüilidade aos povos e a todos Salvação. Sim, que todos experimentem os efeitos de vossa benéfica intercessão, e que, socorridos assim por vós nas misérias desta vida, possamos reunir-nos convosco lá no céu, onde não haverá mais tristeza nem. lágrimas, nem dor, mas uma alegria, uma bem-aventurança eterna. Amém', 'Santos', ARRAY['#catolicoapp', '#intercessao-dos-santos'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Terço da Providência', 'Creio em Deus Pai Todo-poderoso, Criador do Céu e da Terra e em Jesus Cristo, Seu único Filho, nosso Senhor, que foi concebido pelo poder do Espírito Santo, nasceu da Virgem Maria, padeceu sob Pôncio Pilatos, foi crucificado, morto e sepultado; desceu à mansão dos mortos, ressuscitou ao terceiro dia, subiu aos Céus, está sentado à direita de Deus Pai Todo-poderoso, donde há de vir julgar os vivos e os mortos. Creio no Espírito Santo, na Santa Igreja Católica, na comunhão dos santos, na remissão dos pecados, na ressurreição da carne e na vida eterna. Amém!', 'Marianas', ARRAY['#catolicoapp', '#tercos'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, true),
('Oração da Noite', 'Sinal da Cruz Em Nome do Pai, e do Filho e do Espírito Santo. Amém. Pai Nosso Pai-Nosso que estais nos céus, santificado seja vosso nome, venha a nós o vosso reino, seja feita a vossa vontade assim na terra como no céu. O pão nosso de cada dia nos dai hoje, perdoai-nos as nossas ofensas assim como nós perdoamos a quem nos tem ofendido, e não nos deixeis cair em tentação, mas livrai-nos do mal. Amém. Ave Maria Ave Maria, cheia de graça, o Senhor é convosco, bendita sois vós entre as mulheres, e bendito é o fruto do vosso ventre, Jesus . Santa Maria, Mãe de Deus, rogai por nós, pecadores, agora e na hora da nossa morte. Amém.', 'Momentos da Vida', ARRAY['#catolicoapp', '#cotidiano'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Angelus', '℣. O Anjo do Senhor anunciou a Maria ℟. E ela concebeu do Espírito Santo. Ave Maria… ℣. Eis a escrava do Senhor. ℟. Faça-se em mim, segundo a Vossa Palavra. Ave Maria… ℣. E o Verbo Divino encarnou. ℟. E habitou entre nós. Ave Maria… ℣. Rogai por nós, santa Mãe de Deus. ℟. Para que sejamos dignos das promessas de Cristo. ℣. Oremos: Infundi no nosso espírito a vossa graça, ó Pai; Vós que na anunciação do anjo nos revelastes a encarnação do vosso Filho, pela sua Paixão e Cruz, conduzi-nos à glória da ressurreição. Por Cristo, nosso Senhor. ℟. Amém.', 'Diárias', ARRAY['#catolicoapp', '#comuns'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Ladainha da Humildade', 'A Ladainha da Humildade é uma oração simples que nos leva a recordar a necessidade de sermos humildes de coração assim como Jesus. Esta oração foi composta pelo cardeal Merry del Val, amigo próximo do Papa São Pio X.', 'Marianas', ARRAY['#catolicoapp', '#ladainhas'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Ladainha de Nossa Senhora', 'Senhor, tende pidedade de nós Cristo, tende pidedade de nós Senhor, tende pidedade de nós Cristo, ouvi-nos Cristo, atendei-nos Deus Pai do céu, tende piedade de nós Deus Filho Redentor do mundo, tende piedade de nós Deus Espírito Santo, tende piedade de nós Santíssima Trindade, que sois um só Deus, tende piedade de nós Santa Maria, rogai por nós. Santa Mãe de Deus, Santa Virgem das virgens, Mãe de Cristo, Mãe da Igreja, Mãe de misericórdia, Mãe da divina graça, Mãe da esperança, Mãe puríssima, Mãe castíssima, Mãe sempre virgem, Mãe imaculada, Mãe digna de amor, Mãe admirável, Mãe do bom conselho, Mãe do Criador, Mãe do Salvador, Virgem prudentíssima, Virgem venerável, Virgem louvável, Virgem poderosa, Virgem clemente, Virgem fiel, Espelho de perfeição, Sede da Sabedoria, Fonte de nossa alegria, Vaso espiritual, Tabernáculo da eterna glória, Moradia consagrada a Deus, Rosa mística, Torre de Davi, Torre de marfim, Casa de ouro, Arca da aliança, Porta do céu, Estrela da manhã, Saúde dos enfermos, Refúgio dos pecadores, Socorro dos migrantes, Consoladora dos aflitos, Auxílio dos cristãos, Rainha dos Anjos, Rainha dos Patriarcas, Rainha dos Profetas, Rainha dos Apóstolos, Rainha dos Mártires, Rainha dos confessores da fé, Rainha das Virgens, Rainha de todos os Santos, Rainha concebida sem pecado original, Rainha assunta ao céu, Rainha do santo Rosário, Rainha da paz. Cordeiro de Deus, que tirais os pecados do mundo, perdoai-nos, Senhor. Cordeiro de Deus, que tirais os pecados do mundo, ouvi-nos, Senhor. Cordeiro de Deus, que tirais os pecados do mundo, tende piedade de nós. Rogai por nós, santa Mãe de Deus. Para que sejamos dignos das promessas de Cristo.', 'Marianas', ARRAY['#catolicoapp', '#ladainhas'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, false),
('Mistérios Luminosos', 'Como rezar o terço mariano? Sinal da Cruz Em nome do Pai e do Filho e do Espírito Santo. Amém. Oferecimento Divino Jesus, nós Vos oferecemos este terço que vamos rezar, meditando nos mistérios da nossa Redenção. Concedei-nos, por intercessão da Virgem Maria, Mãe de Deus e nossa Mãe, as virtudes que nos são necessárias para bem rezá-lo e a graça de ganharmos as indulgências desta santa devoção. Oferecemos particularmente, em desagravo dos pecados cometidos contra o Santíssimo Coração de Jesus e Imaculado Coração de Maria, pela paz do mundo, pela conversão dos pecadores, pelas almas do Purgatório, pelas intenções do Santo Padre, pelo aumento e santificação do Clero, pelo nosso vigário, pela santificação das famílias, pelas missões, pelos doentes, pelos agonizantes, por todos aqueles que pediram nossas orações, pelo nosso país e por todas as nossas intenções particulares. Credo (Reza-se segurando a cruz do terço) Creio em Deus Pai Todo-Poderoso, Criador do céu e da terra; e em Jesus Cristo, seu único Filho, nosso Senhor; que foi concebido pelo poder do Espí­rito Santo; nasceu da Virgem Maria, padeceu sob Pôncio Pilatos, foi crucificado, morto e sepultado. Desceu à mansão dos mortos; ressuscitou ao terceiro dia; subiu aos céus, está sentado à direita de Deus Pai todo-poderoso, donde há de vir a julgar os vivos e os mortos; creio no Espí­rito Santo, na Santa Igreja Católica, na comunhão dos Santos, na remissão dos pecados, na ressurreição da carne, na vida eterna. Amém. Pai Nosso (Segurando a primeira conta maior após a cruz) Pai-Nosso que estais nos céus, santificado seja vosso nome, venha a nós o vosso reino, seja feita a vossa vontade assim na terra como no céu. O pão nosso de cada dia nos dai hoje, perdoai-nos as nossas ofensas assim como nós perdoamos a quem nos tem ofendido, e não nos deixeis cair em tentação, mas livrai-nos do mal. Amém. Ave Maria (3x) (As três contas menores após a maior) Ave Maria, cheia de graça, o Senhor é convosco, bendita sois vós entre as mulheres, e bendito é o fruto do vosso ventre, Jesus. Santa Maria, Mãe de Deus, rogai por nós, pecadores, agora e na hora da nossa morte. Amém. Glória ao Pai (Na conta maior após as três menores das Ave Maria) Glória ao Pai, e ao Filho e ao Espírito Santo. Como era no princípio, agora e sempre. Amém. Primeiro Mistério Luminoso Batismo de Jesus no Rio Jordão Pai Nosso, 10 Ave Marias, Glória ao Pai Ó meu Jesus, perdoai-nos e livrai-nos do fogo do inferno; levai as almas todas para o Céu, e socorrei principalmente as que mais precisarem. Segundo Mistério Luminoso Revelação de Jesus nas Bodas de Caná Pai Nosso, 10 Ave Marias, Glória ao Pai Ó meu Jesus, perdoai-nos e livrai-nos do fogo do inferno; levai as almas todas para o Céu, e socorrei principalmente as que mais precisarem. Terceiro Mistério Luminoso Anúncio do Reino de Deus Pai Nosso, 10 Ave Marias, Glória ao Pai Ó meu Jesus, perdoai-nos e livrai-nos do fogo do inferno; levai as almas todas para o Céu, e socorrei principalmente as que mais precisarem. Quarto Mistério Luminoso Transfiguração de Nosso Senhor Jesus Cristo Pai Nosso, 10 Ave Marias, Glória ao Pai Ó meu Jesus, perdoai-nos e livrai-nos do fogo do inferno; levai as almas todas para o Céu, e socorrei principalmente as que mais precisarem. Quinto Mistério Luminoso Instituição da Eucaristia Pai Nosso, 10 Ave Marias, Glória ao Pai Ó meu Jesus, perdoai-nos e livrai-nos do fogo do inferno; levai as almas todas para o Céu, e socorrei principalmente as que mais precisarem. Agradecimento Infinitas graças vos damos, soberana Rainha, pelos benefícios que recebe­mos todos os dias de vossas mãos liberais, dignai-vos agora e para sempre tomar-nos debaixo de vosso poderoso amparo, e para mais vos alegrar vos saudamos com uma Salve-Rainha: Salve Rainha! Mãe de misericórdia, vida, doçura, esperança nossa, Salve! A vós bradamos os degredados filhos de Eva. A vós suspiramos, gemendo e chorando neste vale de lágrimas. Eia, pois, advogada nossa, esses vossos olhos misericordiosos a nós volvei, e depois deste desterro, mostrai-nos Jesus, bendito fruto do vosso ventre. O clemente, ó piedosa, ó doce, sempre Virgem Maria. Rogai por nós Santa Mãe de Deus. Para que sejamos dignos das promessas de Cristo. Amém!', 'Marianas', ARRAY['#catolicoapp', '#rosario'], NULL, NULL, 'CatolicoApp (scraping — revisar direitos e texto)', now(), 0, NULL, NULL, true),
